package com.jobpilot.config;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.Map;@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(ResponseStatusException.class)ResponseEntity<?>status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("timestamp",Instant.now(),"message",e.getReason()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?>validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"message",e.getBindingResult().getAllErrors().get(0).getDefaultMessage()));}}
